import { saveDeliveryLocation } from './delivery-context.js';
import { postalRegion } from './marketplace-settings.js';
const buyerStorageKey='temlogoali.buyers.v1';
let activeBuyerId=null;
export function readBuyers(){try{const users=JSON.parse(localStorage.getItem(buyerStorageKey)||'[]');return Array.isArray(users)?users:[]}catch{return []}}
function writeBuyers(users){try{localStorage.setItem(buyerStorageKey,JSON.stringify(users))}catch{throw Error('Não foi possível salvar o cadastro neste navegador. Verifique o armazenamento disponível.')}}
export function currentBuyer(){const user=readBuyers().find(u=>u.id===activeBuyerId);if(!user)return null;const {passwordHash,passwordSalt,...profile}=user;return structuredClone(profile)}
export function logoutBuyer(){activeBuyerId=null;if(typeof window!=='undefined')window.dispatchEvent(new Event('buyer-session-change'))}
function buyerSession(id){activeBuyerId=id;syncBuyerLocation();if(typeof window!=='undefined')window.dispatchEvent(new Event('buyer-session-change'));return currentBuyer()}
function buyerProfile(data){const p={name:String(data.name||'').trim(),email:String(data.email||'').trim().toLowerCase(),phone:String(data.phone||'').replace(/\D/g,''),cpf:String(data.cpf||'').replace(/\D/g,''),birthday:String(data.birthday||'')};if(p.name.length<3||p.name.length>100)throw Error('Informe seu nome completo.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))throw Error('Informe um e-mail válido.');if(!/^\d{10,13}$/.test(p.phone))throw Error('Informe o telefone com DDD.');if(p.cpf&&!/^\d{11}$/.test(p.cpf))throw Error('O CPF demonstrativo deve conter 11 dígitos.');if(p.birthday&&(!/^\d{4}-\d{2}-\d{2}$/.test(p.birthday)||new Date(p.birthday)>new Date()))throw Error('Confira a data de nascimento.');return p}
async function passwordDigest(password,salt){if(!globalThis.crypto?.subtle)throw Error('Este navegador não oferece o recurso necessário ao login local. Use o Chrome atualizado ou o servidor local.');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},material,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function checkBuyerPassword(password){if(typeof password!=='string'||password.length<8||password.length>128)throw Error('Use uma senha demonstrativa de 8 a 128 caracteres.')}
export async function registerBuyer(data){const profile=buyerProfile(data),initialAddress=data.cep?validatedBuyerAddress({...data,label:'Principal'}):null;checkBuyerPassword(data.password);if(data.password!==data.confirmPassword)throw Error('As senhas não conferem.');if(readBuyers().some(u=>u.email===profile.email))throw Error('Este e-mail já está cadastrado. Entre na sua conta.');const passwordSalt=crypto.randomUUID(),passwordHash=await passwordDigest(data.password,passwordSalt);const users=readBuyers();if(users.some(u=>u.email===profile.email))throw Error('Este e-mail já está cadastrado.');const user={...profile,id:crypto.randomUUID(),passwordSalt,passwordHash,addresses:[],defaultDelivery:null,defaultBilling:null,createdAt:new Date().toISOString()};if(initialAddress){initialAddress.id=crypto.randomUUID();user.addresses=[initialAddress];user.defaultDelivery=initialAddress.id;user.defaultBilling=initialAddress.id;}writeBuyers([...users,user]);return buyerSession(user.id)}
export async function loginBuyer(email,password){const user=readBuyers().find(u=>u.email===String(email).trim().toLowerCase());if(!user||await passwordDigest(String(password),user.passwordSalt)!==user.passwordHash)throw Error('E-mail ou senha não conferem.');return buyerSession(user.id)}
export async function updateBuyer(data){const profile=buyerProfile(data),id=activeBuyerId;const original=readBuyers().find(u=>u.id===id);if(!original)throw Error('Entre na sua conta.');const changingCredentials=data.password||profile.email!==original.email;if(changingCredentials&&await passwordDigest(String(data.currentPassword||''),original.passwordSalt)!==original.passwordHash)throw Error('Confirme sua senha atual para alterar e-mail ou senha.');let passwordSalt=original.passwordSalt,passwordHash=original.passwordHash;if(data.password){checkBuyerPassword(data.password);if(data.password!==data.confirmPassword)throw Error('As senhas não conferem.');passwordSalt=crypto.randomUUID();passwordHash=await passwordDigest(data.password,passwordSalt);}const users=readBuyers();if(users.some(u=>u.id!==id&&u.email===profile.email))throw Error('Este e-mail já pertence a outro cadastro.');const user=users.find(u=>u.id===id);Object.assign(user,profile,{passwordSalt,passwordHash});writeBuyers(users);return buyerSession(id)}
function validatedBuyerAddress(data){const address=Object.fromEntries(['label','name','cep','street','number','neighborhood','city','state','complement'].map(k=>[k,String(data[k]||'').trim()]));address.cep=address.cep.replace(/\D/g,'');address.state=address.state.toUpperCase();if(!address.label||!address.name||!/^\d{8}$/.test(address.cep)||!address.street||!address.number||!address.neighborhood||!address.city||! /^[A-Z]{2}$/.test(address.state))throw Error('Preencha identificação, destinatário, CEP, rua, número, bairro, cidade e UF.');return address}
function syncBuyerLocation(){const user=currentBuyer(),a=user?.addresses.find(a=>a.id===user.defaultDelivery);if(a)saveDeliveryLocation(postalRegion(a.cep)?.name||a.city,a.cep)}
export function saveBuyerAddress(data){const users=readBuyers(),user=users.find(u=>u.id===activeBuyerId);if(!user)throw Error('Entre na sua conta.');const address=validatedBuyerAddress(data);if(data.id&&!user.addresses.some(a=>a.id===data.id))throw Error('Endereço não encontrado.');address.id=data.id||crypto.randomUUID();user.addresses=user.addresses.filter(a=>a.id!==address.id).concat(address);if(data.delivery||!user.defaultDelivery)user.defaultDelivery=address.id;if(data.billing||!user.defaultBilling)user.defaultBilling=address.id;writeBuyers(users);syncBuyerLocation();return currentBuyer()}
export function removeBuyerAddress(id){const users=readBuyers(),user=users.find(u=>u.id===activeBuyerId);if(!user||!user.addresses.some(a=>a.id===id))throw Error('Endereço não encontrado.');user.addresses=user.addresses.filter(a=>a.id!==id);if(user.defaultDelivery===id)user.defaultDelivery=user.addresses[0]?.id||null;if(user.defaultBilling===id)user.defaultBilling=user.addresses[0]?.id||null;writeBuyers(users);syncBuyerLocation();return currentBuyer()}
export function ownsBuyerOrder(order){return !!activeBuyerId&&order?.buyerId===activeBuyerId}
export function updateBuyerHeader(){if(typeof document==='undefined')return;const user=currentBuyer();document.querySelectorAll('.header-action.account').forEach(b=>{let label=b.querySelector('[data-buyer-greeting]');if(!label){b.innerHTML=(b.querySelector('svg')?.outerHTML||'')+'<span data-buyer-greeting></span>';label=b.querySelector('[data-buyer-greeting]');}label.textContent=user?'Bem-vindo, '+user.name.split(' ')[0]+'!':'Entre ou cadastre-se';b.setAttribute('aria-label',user?'Minha conta de '+user.name:'Entrar ou cadastrar sua conta');});}
if(typeof window!=='undefined'){window.addEventListener('buyer-session-change',updateBuyerHeader);window.addEventListener('pageshow',e=>{if(e.persisted){logoutBuyer();document.querySelector('#modal')?.close()}});}
